    (Re)Initialize the objects
    """
    objects = [Player()]

    objects.extend([None] * 5)
    if hud:
        objects.extend([None] * 4)
    return objects


def _detect_objects_ram(objects, ram_state, hud=False):
    """
    For all 3 objects:
    (x, y, w, h, r, g, b)
    """

    # player x,y == r27 - 1, 50 + r25 
    player = objects[0]
    player.xy = ram_state[27] - 1, 50 + ram_state[25]

    # row1 x,y == r61, 57
    if ram_state[49] != 255:
        if objects[1] is None:
            if ram_state[49] == 6:
                row1 = Helicopter()
            else:
                row1 = Ice()
            objects[1] = row1
        else:
            row1 = objects[1]
        row1.xy = ram_state[61] - 1, 57
    else:
        objects[1] = None

    # row2 x,y == r59, 57
    if ram_state[50] != 255:
        if objects[2] is None:
            # if ram_state[50] == 140:
            row2 = Hornet()
            objects[2] = row2
        else:
            row2 = objects[2]
        row2.xy = ram_state[59] - 2, 75
    else:
        objects[2] = None

    # pshot xy = r38, r31
    if ram_state[31] != 128:
        p_shot = Player_Shot()
        objects[3] = p_shot
        p_shot.xy = ram_state[38] - 11, 55 + ram_state[31]
    else:
        objects[3] = None

    # eshot xy = r39, r30
    if ram_state[30] != 128:
        e_shot = Enemy_Shot()
        objects[4] = e_shot
        e_shot.xy = ram_state[39] - 11, 55 + ram_state[30]
    else:
        objects[4] = None

    # fire hole x == 43
    # erupt == r51; x == r60; size == r109, 86 == small, 102 == big
    if ram_state[51] == 54 and ram_state[108] == 251:
        erup = Eruption()
        objects[5] = erup
        if ram_state[109] == 86:
            erup.xy = ram_state[60] + 4, 125
            erup.wh = 20, 7
        else:
            erup.xy = ram_state[60], 125
            erup.wh = 32, 15
    elif ram_state[51] == 48:
        div = Diver()
        objects[5] = div
        div.xy = ram_state[60] - 1, 131
    elif ram_state[108] == 250:
        if type(objects[5]) == Fire_Hole:
            hole = objects[5]
        else:
            hole = Fire_Hole()
            objects[5] = hole
        hole.xy = ram_state[43], 122
    else:
        objects[5] = None


    if hud:
        # Score
        score = Score()
        objects[6] = score
        if ram_state[94] > 15:
            score.xy = 55, 15
            score.wh = 46, 7
        elif ram_state[94]:
            score.xy = 63, 15
            score.wh = 38, 7
        elif ram_state[93] > 15:
            score.xy = 71, 15
            score.wh = 30, 7
        elif ram_state[93]:
            score.xy = 79, 15
            score.wh = 22, 7
        elif ram_state[92] > 15:
            score.xy = 87, 15
            score.wh = 14, 7
        else:
            score.xy = 95, 15
            score.wh = 6, 7

        # Lives 86
        for i in range(3):
            if i < ram_state[111]:
                life = Life()
                objects[7+i] = life
                life.xy = 9+(i*16), 184
            else:
                objects[7+i] = None

