    # ram[37-40] == x, ram[33-36] == y, odd player, even enemy
    # x == 69 -> 80, x == 80 -> 91
    # y == 100 -> 59, y == 99 -> 60

    # ram[94] == player_x
    objects[0].xy = ram_state[94] - 70, 173

    if not ram_state[84]:
        objects[1] = Player_Projectile()
        objects[1].xy = ram_state[93] - 71, 201 - ram_state[89]

    for i in range(4):
        if ram_state[58+i] < 250:
            left = ram_state[80+i]>>4
            right = ram_state[80+i]&15
            if left&8:
                x = 5 + (right-3) * 15 + (left^15) + 1
            else:
                x = 5 + (right-3) * 15 - left

            objects[2+i] = Enemy_Projectile()
            objects[2+i].xy = x, 189 - ram_state[58+i]
        else:
            objects[2+i] = None

    if ram_state[11]:
        # ram[99-106] == enemy_x
        # ram[41-44] == enemy_y, ram[41] corresponds to ram[99] and ram[103] and so on
        # ram[27-30] == left side types, ram[34-37] == right side types

        if ram_state[27]&64:
            if ram_state[27]&32:
                rgb = 158, 208, 101
            else:
                # orange
                rgb = 227, 151, 89
            for i in range(4):
            # left side enemies
                if ram_state[27+i]&6 == 6:
                    enemy = None
                else:
                    enemy = Phoenix()
                    enemy.rgb = rgb
                    # enemy.xy = ram_state[99+i] - 70, 204 - ram_state[41+i]
                    enemy.xy = ram_state[99+i] - 70, 204 - ram_state[41+i]

                #right side enemies
                if ram_state[34+i]&6 == 6:
                    enemy2 = None
                else:
                    enemy2 = Phoenix()
                    enemy2.rgb = rgb
                    enemy2.xy = ram_state[103+i] - 70, 204 - ram_state[41+i]

                objects[5+i] = enemy
                objects[9+i] = enemy2
        else:
            # ram[27-33] == left wing, ram[34-40] == right wing    
            if ram_state[27]&32:
                # red
                rgb = 167, 26, 26
            else:
                # blue
                rgb = 24, 26, 167
            for i in range(7):
                wing_left = ram_state[27+i]&15
                if wing_left < 8:
                    bat = Bat()
                    x = ram_state[99+i] - 65
                    w, h = 8, 10
                    # left wing
                    if wing_left < 7:
                        if wing_left == 3:
                            x-=3
                            w+=2
                            h+=1
                        elif wing_left == 6:
                            x-=4
                            w+=4
                            h-=1
                        else:
                            x-=4
                            w+=4
                    else:
                        bat.wing = 1

                    # right wing

                    wing_right = ram_state[34+i]&15
                    if wing_right < 7:
                        if wing_right == 3:
                            w+=4
                        else:
                            w+=4
                    else:
                        bat.wing = bat.wing&2

                    # bat orientation
                    if ram_state[63]&2**i:
                        x-=2
                        bat.orientation = 1

                    bat.xy = x, 201 - ram_state[41+i]
                    bat.wh = w, h
                    bat.rgb = rgb
                    objects[5+i] = bat

                else:
                    objects[5+i] = None
            objects[12] = None
        for i in range(13, 169):
            objects[i] = None
    else:
