            pshot.xy = ram_state[73] - 5, 176 - ram_state[75]
        else:
            pshot.xy = ram_state[74] - 5, 176 - ram_state[76]
    else:
        objects[1] = None

    if level == 0:
        if ram_state[36] != 140:
            # player color
