                x, y = ram_state[37+i] - 4, 165 - ram_state[41+i]
                w, h = 8, 7
                if ram_state[45+i]%8 == 0 or ram_state[45+i]%8 == 4:
                    y+=1
                    h+=2
                elif ram_state[45+i]%8 == 1 or ram_state[45+i]%8 == 7:
                    h+=3
                elif ram_state[45+i]%8 == 2 or ram_state[45+i]%8 == 6:
                    y+=2
                elif ram_state[45+i]%8 == 3:
                    x+=1
                    w-=1
                    h+=4
                elif ram_state[45+i]%8 == 5:
                    w-=1
                    h+=4

                # if enemy out of bounds, will appear at the opposing border
                if 0 < y < 33 or x < 0:
                    enemy2 = Enemy_Green()
                    objects[9+i] = enemy2
                    x2, y2 = x, y
                    w2, h2 = w, h
                    if x < 4:
                        x2 = 160+x
                        w2 = -x
                        w += x
                        x = 0
                    if y < 33:
                        y2 = y + 144
                        h2 = 33 - y
                        h -= (33-y)
                        y = 33
                    enemy2.xy = x2, y2
                    enemy2.wh = w2, h2
                else:
                    objects[9+i] = None
                enemy.xy = x, y
                enemy.wh = w, h
            else:
                objects[3+i] = None
                objects[9+i] = None

        # Enemy shots
        for i in range(2):
