def _detect_objects_ram(objects, ram_state, hud=False):
    """
    For all 3 objects:
    (x, y, w, h, r, g, b)
    """

    # type == r36-r39; x, y == r40-r43, r56-r59

    for i in range(4):
        x, y = ram_state[40+i], ram_state[56+i] + 16
        if ram_state[36+i] == 23:
            objects[i] = None
        elif ram_state[36+i] == 16:
            player = Player()
            objects[i] = player
            player.xy = x, y
        elif ram_state[36+i] < 8:
            w, h = 16, 16
            truck = Truck()
            objects[i] = truck

            # truck colors and offsets
            if ram_state[36+i] == 0:
                truck.rgb = 213, 130, 74
            elif ram_state[36+i] == 1:
                truck.rgb = 214, 92, 92
                x+=2
                w-=2
            elif ram_state[36+i] == 2:
                truck.rgb = 92, 186, 92
                y+=1
                h-=1
            elif ram_state[36+i] == 3:
                truck.rgb = 84, 160, 197
            elif ram_state[36+i] == 4:
                truck.rgb = 164, 89, 208
            elif ram_state[36+i] == 5:
                truck.rgb = 127, 92, 213
                w-=2
            elif ram_state[36+i] == 6:
                truck.rgb = 84, 92, 214
                y+=2
                h-=2
            elif ram_state[36+i] == 7:
                truck.rgb = 84, 138, 210
            truck.xy = x, y
            truck.wh = w, h
        elif ram_state[36+i] < 16 or 23 < ram_state[36+i] < 31:

            # is flag or collectable; they have the same colors
            if ram_state[36+i] < 16:
                col = Flag()
            else:
                col = Collectable()
            objects[i] = col
            if ram_state[36+i]%16 == 8:
                col.rgb = 104, 72, 198
            elif ram_state[36+i]%16 == 9:
                col.rgb = 162, 162, 42
            elif ram_state[36+i]%16 == 10:
                col.rgb = 146, 70, 192
            elif ram_state[36+i]%16 == 11:
                col.rgb = 184, 70, 162
            elif ram_state[36+i]%16 == 12:
                col.rgb = 200, 72, 72
            elif ram_state[36+i]%16 == 13:
                col.rgb = 139, 108, 58
            elif ram_state[36+i]%16 == 14:
                col.rgb = 180, 122, 48
            elif ram_state[36+i]%16 == 15:
                col.rgb = 66, 72, 200
            col.xy = x, y - 1
        else:
            objects[i] = None

    if hud:
        if not ram_state[4]&1:
            hf = HUD_Flag()
            objects[-13] = hf
            hf.rgb = 78, 50, 181
            hf.xy = 91, 14
            hf.wh = 5, 12
        else:
            objects[-13] = None
        if not ram_state[4]&2:
            hf = HUD_Flag()
            objects[-12] = hf
            hf.rgb = 134, 134, 29
            hf.xy = 19, 14
            hf.wh = 5, 12
        else:
            objects[-12] = None
        if not ram_state[4]&4:
            hf = HUD_Flag()
            objects[-11] = hf
            hf.rgb = 125, 48, 173
            hf.xy = 107, 14
            hf.wh = 5, 12
        else:
            objects[-11] = None
        if not ram_state[4]&8:
            hf = HUD_Flag()
            objects[-10] = hf
            hf.rgb = 168, 48, 143
            hf.xy = 127, 14
            hf.wh = 5, 12
        else:
            objects[-10] = None
        if not ram_state[4]&16:
            hf = HUD_Flag()
            objects[-9] = hf
            hf.rgb = 184, 50, 50
            hf.xy = 71, 14
            hf.wh = 5, 12
        else:
            objects[-9] = None
        if not ram_state[4]&32:
            hf = HUD_Flag()
            objects[-8] = hf
            hf.rgb = 181, 83, 40
            hf.xy = 55, 14
            hf.wh = 5, 12
        else:
            objects[-8] = None
        if not ram_state[4]&64:
            hf = HUD_Flag()
            objects[-7] = hf
            hf.rgb = 162, 98, 33
            hf.xy = 35, 14
            hf.wh = 5, 12
        else:
            objects[-7] = None
        if not ram_state[4]&128:
            hf = HUD_Flag()
            objects[-6] = hf
            hf.rgb = 45, 50, 184
            hf.xy = 143, 14
            hf.wh = 5, 12
        else:
            objects[-6] = None

        # Score
        score = Score()
        objects[-5] = score
        x, w= 57, 5
        if ram_state[0] > 16:
            x, w = 17, 45
        elif ram_state[0]:
            x, w = 25, 37
        elif ram_state[1] > 16:
            x, w = 33, 29
        elif ram_state[1]:
            x, w = 41, 21
        elif ram_state[2]:
            x, w = 49, 13

        score.xy = x, 6
        score.wh = w, 7


        # Lives r6
        for i in range(4):
            if ram_state[6]%5 > i:
                life = Life()
                objects[-4+i] = life
                life.xy = 16+(8*i), 196
            else:
                objects[-4+i] = None

